# Iterate over n and k, and solve for x.
def check_n_k_efficient(n_max, k_max):
    solutions = []
    for n in range(2, n_max + 1):
        for k in range(1, k_max + 1):
            target = 2**k + 2
            # solve x^n + x = target
            # Since x^n + x is increasing, we can use binary search
            low = n + 1
            high = target
            # Actually, high can be smaller
            if n > 1:
                high = int(target**(1/n)) + 2

            while low <= high:
                mid = (low + high) // 2
                val = mid**n + mid
                if val == target:
                    if mid > n:
                        solutions.append((mid, n, k))
                    break
                elif val < target:
                    low = mid + 1
                else:
                    high = mid - 1
    return sorted(list(set(solutions)))

